edits.after:
verifyRetirement(context:C,operation:Readonly<VoiceMetadata>,proof:unknown):VoiceRetirement;
/** Production binds ONLY original private observation owner; missing refuses new branch. */
requireObservedSpeechSource?(context:C,original:Readonly<AttachedSpeechOriginal>,owner:Readonly<VoiceOwner>):void;

if(Object.hasOwn(value,"assistantSpeechSource")) {
  const tag=value.assistantSpeechSource;
  exact(tag,["version","kind","sourceId","sourceHash","callId","callGeneration","planHash","profileDigest","voiceId","segmentIndex","segmentCount","segmentSha256","cpuInputSha256"]);
  if(tag.version!==1||tag.kind!=="assistant-content-observation"||!uuid(tag.sourceId)||!hash(tag.sourceHash)||!text(tag.callId,128)
    ||!integer(tag.callGeneration)||!hash(tag.planHash)||!hash(tag.profileDigest)||!text(tag.voiceId,64)
    ||!integer(tag.segmentIndex)||!integer(tag.segmentCount)||tag.segmentCount<1||tag.segmentCount>512||tag.segmentIndex>=tag.segmentCount
    ||!hash(tag.segmentSha256)||!hash(tag.cpuInputSha256)||value.kind!=="voice-speech-tts"||cpu?.kind!=="synthesize"
    ||value.parentOperationId===null||value.parentOperationId!==value.controlOperationId||tag.cpuInputSha256!==value.inputSha256)return fail("VOICE_ASSISTANT_SOURCE_INVALID",422);
  return Object.freeze({...value,scope,cpuIdentity:cpu,assistantSpeechSource:Object.freeze({...tag})}) as VoiceOriginal;
}
return Object.freeze({...value,scope,cpuIdentity:cpu}) as VoiceOriginal;

if(original.assistantSpeechSource) {
  const tag=original.assistantSpeechSource;
  if(original.kind!=="voice-speech-tts"||original.parentOperationId!==original.controlOperationId||!original.controlOperationId
    ||typeof ports.requireObservedSpeechSource!=="function")return fail("VOICE_ASSISTANT_ORIGINAL_REQUIRED",403);
  // Actual fixed API owner resolves module-private original payload/plan;
  // a tag, SQL row or callback returning true is never that authority.
  if(ports.requireObservedSpeechSource(context,original as AttachedSpeechOriginal,originalOwner)!==undefined)return fail("VOICE_ASSISTANT_ORIGINAL_REQUIRED",403);
  const source=ports.db().prepare("SELECT * FROM veyra_voice_assistant_speech_sources WHERE source_id=?").get(tag.sourceId);
  const control=get(original.controlOperationId);
  if(!source||!control||control.kind!=="voice-cpu-supervisor"||control.state!=="running"||control.resource_retired!==0
    ||control.scope_hash!==digest(original.scope)||!equal(JSON.parse(control.owner_json),originalOwner)
    ||JSON.parse(control.control_json).profileDigest!==tag.profileDigest
    ||source.metadata_hash!==tag.sourceHash||digest(JSON.parse(source.metadata_json))!==tag.sourceHash
    ||source.scope_hash!==digest(original.scope)||source.control_operation_id!==original.controlOperationId
    ||source.control_owner_hash!==digest(originalOwner)||source.call_id!==tag.callId||source.call_generation!==tag.callGeneration
    ||source.turn_generation!==original.turnGeneration||source.deadline_at<original.deadlineAt||source.deadline_at<=ports.now()
    ||source.user_epoch!==current.userSecurityEpoch||source.workspace_epoch!==current.workspaceSecurityEpoch||source.runtime_epoch!==current.runtimeSecurityEpoch
    ||ports.db().prepare("SELECT 1 FROM veyra_voice_assistant_speech_tombstones WHERE source_id=?").get(tag.sourceId))return fail("VOICE_ASSISTANT_SOURCE_UNAVAILABLE",403);
  const priorPlan=ports.db().prepare("SELECT plan_hash,profile_digest,voice_id,segment_count FROM veyra_voice_assistant_speech_claims WHERE source_id=? LIMIT 1").get(tag.sourceId);
  if(priorPlan&&(priorPlan.plan_hash!==tag.planHash||priorPlan.profile_digest!==tag.profileDigest||priorPlan.voice_id!==tag.voiceId||priorPlan.segment_count!==tag.segmentCount))return fail("VOICE_ASSISTANT_PLAN_CONFLICT");
  // Same original Core write transaction; source/control guards and
  // immutable unique claims in migration134 are REQUIRED before activation.
  if(ports.db().prepare("SELECT 1 FROM veyra_voice_assistant_speech_claims WHERE source_id=? AND segment_index=?").get(tag.sourceId,tag.segmentIndex))return fail("VOICE_ASSISTANT_SEGMENT_SPENT");
  ports.db().prepare("INSERT INTO veyra_voice_assistant_speech_claims(source_id,segment_index,segment_count,plan_hash,profile_digest,voice_id,segment_sha256,input_sha256,operation_id) VALUES(?,?,?,?,?,?,?,?,?)")
    .run(tag.sourceId,tag.segmentIndex,tag.segmentCount,tag.planHash,tag.profileDigest,tag.voiceId,tag.segmentSha256,original.inputSha256,original.operationId);
} else
if(original.parentOperationId){
  const parent=get(original.parentOperationId);
  if(!parent||parent.scope_hash!==digest(original.scope)||parent.turn_generation!==original.turnGeneration||parent.kind!=="voice-agent-turn"||parent.deadline_at<=ports.now()
    ||(original.kind==="voice-speech-tts"?parent.state!=="terminal"||parent.outcome!=="completed"||!parent.result_fingerprint:parent.state!=="running"))return fail("VOICE_PARENT_UNAVAILABLE",403);
}
